      material: .opaque,
      corners: .smooth,
      imageScaling: .smooth,
      textGrid: 0,
      components: [
        "banner": [
          "borderColor": "color-border-emphasized",
          "borderWidth": "border-width",
          "cornerRadius": "radius-element",
        ],
        "button": [
          "borderColor": "color-border-emphasized",
          "borderWidth": "border-width",
        ],
        "card": [
          "borderColor": "color-border-emphasized",
          "borderWidth": "border-width",
          "cornerRadius": "radius-element",
          "padding": "spacing-6",
        ],
        "text-input": [
          "borderColor": "color-border-emphasized",
          "borderWidth": "border-width",
        ],
      ],
      icons: [
        "check": .system("checkmark"),
        "close": .system("xmark"),
        "error": .system("xmark.square.fill"),
        "info": .system("info.square.fill"),
        "success": .system("checkmark.square.fill"),
        "warning": .system("exclamationmark.triangle.fill"),
      ]
    )
  )
}
